def dx(data, to_bytes=False):
    """Phase VI: XOR Decoder for string obfuscation"""
    if not data or not XOR_KEY: return ""
    res = bytes([b ^ XOR_KEY[i % len(XOR_KEY)] for i, b in enumerate(data)])
