def resolve_api(lib_name, api_name):
    """Phase VI: Dynamic API Resolution to bypass IAT analysis"""
    if os.name != 'nt': return None
    try:
        kernel32 = ctypes.windll.kernel32
        h_mod = kernel32.GetModuleHandleW(lib_name)
        if not h_mod: 
            h_mod = kernel32.LoadLibraryW(lib_name)
        addr = kernel32.GetProcAddress(h_mod, api_name.encode() if isinstance(api_name, str) else api_name)
        if not addr: return None
        return addr
    except: return None
