def get_device_id():
    return str(uuid.uuid5(uuid.NAMESPACE_DNS, str(uuid.getnode())))
def get_location_info():
    apis = [
        ('http://ip-api.com/json', lambda d: {'ip': d.get('query', 'Unknown'), 'country': d.get('country', 'Unknown'), 'location': f"{d.get('city', '')}, {d.get('country', '')}"}),
        ('https://ipinfo.io/json', lambda d: {'ip': d.get('ip', 'Unknown'), 'country': d.get('country', 'Unknown'), 'location': f"{d.get('city', '')}, {d.get('country', '')}"})
    ]
    for url, parser in apis:
        try:
            req = urllib.request.Request(url, headers={'User-Agent': 'curl/7.64.1'})
            with urllib.request.urlopen(req, timeout=10) as response:
                data = json.loads(response.read().decode())
                result = parser(data)
                if result['ip'] not in ('', 'Unknown', None):
                    return result
        except:
            continue
    return {'ip': 'Unknown', 'country': 'Unknown', 'location': 'Unknown'}
def get_device_info():
    loc_data = get_location_info()
    uname = platform.uname()
    raw_user = getpass.getuser()
    raw_id = get_device_id()
    hashed_user = hashlib.sha256(raw_user.encode()).hexdigest()
    hashed_id = hashlib.sha256(raw_id.encode()).hexdigest()
    return {
        'device_info_str': f"{loc_data['location']} | {uname.system} {uname.release} | {raw_user} | {raw_id}",
        'ip_address': loc_data['ip'],
        'location': loc_data['location'],
        'username': raw_user,
        'os_type': uname.system,
        'device_id': raw_id,
        'parent_id': PARENT_ID
    }
